### Contoh

```js
const server = app.listen(config.PORT, () => log.info({ port: config.PORT }, 'Toko API siap'));

async function berhenti(sinyal) {
  log.info({ sinyal }, 'Menerima sinyal, menutup server');
  server.close(async () => {          // tunggu permintaan berjalan selesai
    await prisma.$disconnect();
    log.info('Server ditutup dengan rapi');
    process.exit(0);
  });
  setTimeout(() => process.exit(1), 10_000).unref(); // batas waktu
}
process.on('SIGTERM', berhenti);
process.on('SIGINT', berhenti);       // Ctrl+C
```

Untuk mencoba tanpa menunggu, `timeout -s TERM 3 npm start` menjalankan server dan mengirim SIGTERM setelah 3 detik.

